-- idea-to-pr: generated by `npm run guide:content` from content/guide/idea-to-pr.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 17,
  "outcome": "Вы проводите одну настоящую задачу своего проекта от идеи до слитого PR, используя весь маршрут, и знаете, где вмешивались сами.",
  "blocks": [
    {
      "type": "scene",
      "text": "Коллега освоил все приёмы по отдельности: план — иногда, ревьюер — когда вспомнит, тесты — если успеет. Каждая задача шла по-своему, и ошибки проскакивали именно в пропущенных звеньях. Приёмы работают как цепочка: выпадает одно звено — и проверка держится на удаче."
    },
    {
      "type": "text",
      "text": "Пройденные этапы — это части одного процесса. Здесь вы собираете их в одну цепочку на реальной задаче: не учебной, а той, что всё равно стоит в вашем списке. Проверки в конце нет: результат — ваш PR."
    },
    {
      "type": "bridge",
      "text": "Перед первым боевым релизом вы прогоняли пробный: весь путь от ветки до продакшена на настоящем, но небольшом изменении, чтобы увидеть, где процесс скрипит. Выпускная задача — такой же прогон для работы с агентом."
    },
    {
      "type": "why",
      "text": "Каждый приём закрывает свой тип ошибок: критерий — неясную цель, план — неверное допущение, шаги — разросшийся diff, ревью в чистом контексте — слепые пятна автора, CI — забытую проверку. По отдельности они помогают, но ошибка проходит там, где звено пропущено. Поэтому проверяют не приёмы, а цепочку целиком."
    },
    {
      "type": "heading",
      "text": "Маршрут одной задачи"
    },
    {
      "type": "list",
      "items": [
        "**Задача с критерием**: что должно работать и как это проверить (шаг 3.1).",
        "**Исследование** в субагенте: где это в коде, что уже есть (шаг 6.1).",
        "**План** в режиме планирования, а правки — только после согласования (шаг 3.2).",
        "**Шаги**, каждый с проверкой: тест, сборка, ручной сценарий (шаги 3.3 и 3.4).",
        "**Ревью**: diff, тесты как контракт, безопасность (шаги 4.1–4.4), лучше — ревьюер в чистом контексте (шаг 6.3).",
        "**Коммиты и PR** по правилам проекта, CI проверяет за вас (шаги 5.4 и 5.5)."
      ]
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция всей задачи: разработчик ставит задачу «экспорт заказов в CSV» с критерием, агент исследует код субагентом, предлагает план, выполняет его по шагам с тестами, ревьюер в чистом контексте находит пропущенное экранирование, после исправления агент делает коммит и открывает PR, CI проходит.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Экспорт заказов в CSV. Готово, если файл открывается в Excel и тест экспорта зелёный. Сначала план.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Explore: заказы — src/orders, похожий экспорт — src/reports/csv.ts"
        },
        {
          "kind": "meta",
          "text": "План: 3 шага, правок нет до согласования"
        },
        {
          "kind": "edit",
          "text": "src/orders/export.ts",
          "diff": "+64"
        },
        {
          "kind": "pass",
          "text": "npm test -- orders — пройдено"
        },
        {
          "kind": "info",
          "text": "reviewer: запятые и кавычки в названиях товаров не экранируются"
        },
        {
          "kind": "edit",
          "text": "src/orders/export.ts",
          "diff": "+9 −2"
        },
        {
          "kind": "command",
          "text": "gh pr create --title \"feat: export orders to CSV\"",
          "typed": true
        },
        {
          "kind": "done",
          "text": "PR открыт, CI зелёный. Осталось ваше ревью и слияние."
        }
      ]
    },
    {
      "type": "code",
      "file": "docs/capstone.md",
      "code": "# Выпускная задача\n\nЗадача:\nКритерий готовности:\n\n## Ход работы\n- [ ] исследование (субагент)\n- [ ] план согласован\n- [ ] шаги с проверками\n- [ ] ревью в чистом контексте\n- [ ] PR и зелёный CI\n\n## Где я вмешался\n- \n\n## Что агент сделал без меня\n- ",
      "caption": "Ведите заметки по ходу: раздел «Где я вмешался» понадобится в следующем шаге."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Не берите «переписать всё»",
      "text": "Выпускная задача должна быть настоящей, но обозримой: на день-два работы, с понятным критерием. Огромная задача проверяет терпение, а не процесс."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Сливаете вы, а не агент",
      "text": "Последнее решение остаётся за вами: прочитайте итоговый diff целиком, как чужой PR, и только потом сливайте (шаг 4.1)."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Лучшие практики: исследовать, спланировать, сделать, закоммитить",
          "url": "https://code.claude.com/docs/en/best-practices"
        },
        {
          "title": "Типовые сценарии: от задачи до пулл-реквеста",
          "url": "https://code.claude.com/docs/en/common-workflows"
        }
      ]
    }
  ],
  "practice": {
    "task": "Выберите реальную задачу своего проекта и проведите её по всему маршруту: критерий, исследование, план, шаги с проверками, ревью в чистом контексте, PR. Ведите заметки по шаблону выше.",
    "done": [
      "PR слит или готов к слиянию, CI зелёный;",
      "у задачи был критерий, и он выполнен;",
      "вы записали, где вмешивались сами и почему."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  }
}$json$::jsonb where step_id = 'idea-to-pr';
delete from private.guide_checks where step_id = 'idea-to-pr';

-- before-after: generated by `npm run guide:content` from content/guide/before-after.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 14,
  "outcome": "Вы сравниваете, как работали раньше и как работаете с агентом, на цифрах и фактах, а не на ощущениях.",
  "blocks": [
    {
      "type": "scene",
      "text": "Через месяц работы с агентом вас спрашивают: «Ну как, быстрее?» Вы отвечаете «раза в три» — и не можете показать, откуда эта цифра. Потом вспоминаете два вечера, ушедших на ревью и переделки, и цифра становится «наверное, в полтора»."
    },
    {
      "type": "text",
      "text": "Ощущение «стало быстрее» обманчиво: время на ревью и переделки легко не заметить. Честное сравнение показывает, что действительно изменилось, и где агент пока не помогает."
    },
    {
      "type": "bridge",
      "text": "Вы мерили производительность до и после оптимизации: один и тот же сценарий, одни и те же метрики, а не «стало шустрее». С агентом так же: похожие задачи и одинаковые замеры."
    },
    {
      "type": "why",
      "text": "Агент сокращает заметную часть работы — набор кода, поиск по проекту — и добавляет незаметную: постановку, ревью, переделки. Ощущение запоминает первое и забывает второе. Только сравнение похожих задач по одним метрикам показывает, где выигрыш настоящий, а где проходит ваша граница делегирования."
    },
    {
      "type": "heading",
      "text": "Что измерять"
    },
    {
      "type": "list",
      "items": [
        "**Время** от задачи до PR, включая ревью и исправления.",
        "**Ручная работа**: сколько правок вы внесли сами и почему.",
        "**Ошибки до слияния**: что поймали тесты, хуки и ревьюер, а что — только вы.",
        "**Граница делегирования**: какие задачи вы теперь отдаёте целиком, а какие оставили себе (шаг 4.5)."
      ]
    },
    {
      "type": "compare",
      "before": {
        "label": "Было",
        "text": "Экспорт отчёта в CSV: два дня. Сам искал похожий код, сам писал тесты, баг с кавычками нашли пользователи.",
        "note": "Время уходило на поиск и рутину, а проверка держалась на внимательности."
      },
      "after": {
        "label": "Стало",
        "text": "Экспорт заказов в CSV: полдня. Агент нашёл образец и написал код по плану, ревьюер поймал кавычки до PR, CI проверил сборку.",
        "note": "Моя работа — критерий, план, ревью и решение о слиянии."
      }
    },
    {
      "type": "code",
      "file": "docs/before-after.md",
      "code": "# Было / Стало\n\n| | Было | Стало |\n|---|---|---|\n| Задача | | |\n| Время до PR | | |\n| Правок руками | | |\n| Ошибки до слияния | | |\n\n## Что отдаю агенту целиком\n- \n\n## Что оставляю себе и почему\n- ",
      "caption": "Сравнивайте похожие задачи. Колонку «Стало» заполните по заметкам из шага ★.1."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Сравнивайте похожее",
      "text": "Не ставьте лучшую новую задачу рядом с худшей старой. Берите задачи одного размера и типа — иначе сравнение покажет удачу, а не процесс."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "«Не стало лучше» — тоже результат",
      "text": "Если где-то агент не ускорил работу, это ценная находка: там проходит ваша граница делегирования. Запишите её, чтобы не тратить время повторно."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Лучшие практики: где агенту нужна ваша проверка",
          "url": "https://code.claude.com/docs/en/best-practices"
        }
      ]
    }
  ],
  "practice": {
    "task": "Заполните «Было / Стало» по шаблону: возьмите задачу из шага ★.1 и похожую задачу, сделанную раньше без агента. Отдельно запишите, что вы теперь отдаёте агенту целиком, а что оставляете себе.",
    "done": [
      "обе колонки заполнены фактами, а не впечатлениями;",
      "сравниваются задачи похожего размера;",
      "записано хотя бы одно место, где агент пока не помогает."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  }
}$json$::jsonb where step_id = 'before-after';
delete from private.guide_checks where step_id = 'before-after';

-- public-profile: generated by `npm run guide:content` from content/guide/public-profile.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 14,
  "outcome": "Вы собираете результат маршрута в одном месте проекта: цикл задачи, образец PR, «Было / Стало» и настройки агента — опору для себя и команды на следующие задачи.",
  "blocks": [
    {
      "type": "scene",
      "text": "Новый коллега спрашивает, как у вас принято работать с агентом. Вы начинаете рассказывать и понимаете: половина правил живёт у вас в голове, четверть — в старых сессиях, а в репозитории лежит только CLAUDE.md трёхмесячной давности."
    },
    {
      "type": "text",
      "text": "Маршрут вы проходили по шагам, но польза — в системе: правилах, проверках и привычках, которые остаются в проекте. Этот шаг собирает их в одном месте, чтобы следующая задача начиналась не с нуля."
    },
    {
      "type": "bridge",
      "text": "Вы писали для команды инженерный handbook: как ревьюим, как релизим, где что настроено. `docs/agents.md` — такой handbook для работы с агентами: короткий, рядом с кодом и со ссылками на настоящие настройки."
    },
    {
      "type": "why",
      "text": "Разговор с агентом не переходит из сессии в сессию, а устные договорённости уходят вместе с вашим вниманием. Устойчиво только то, что лежит в репозитории: CLAUDE.md, настройки, хуки, навыки и файл, который связывает их в процесс. Он делает систему видимой — и для команды, и для вас через полгода."
    },
    {
      "type": "heading",
      "text": "Что собрать"
    },
    {
      "type": "list",
      "items": [
        "**Цикл задачи**: критерий, план, шаги с проверками, ревью, PR — как он сложился у вас.",
        "**Образец**: PR из шага ★.1 и «Было / Стало» из шага ★.2.",
        "**Настройки проекта**: CLAUDE.md, правила разрешений, хуки, свои команды и субагенты (этапы 2, 5 и 6).",
        "**Что дальше**: какие задачи вы теперь отдадите агенту целиком."
      ]
    },
    {
      "type": "code",
      "file": "docs/agents.md",
      "code": "# Как мы работаем с агентами\n\n## Цикл задачи\nКритерий → план → шаги с проверками → ревью в чистом контексте → PR\n\n## Образец\n- [Экспорт заказов в CSV](ссылка на PR)\n- Было / Стало: [сравнение](before-after.md)\n\n## Настройки\n- Правила проекта: [CLAUDE.md](../CLAUDE.md)\n- Разрешения и хуки: `.claude/settings.json`\n- Команды и субагенты: `.claude/skills/`, `.claude/agents/`\n\n## Дальше\n- [Задача, которую отдам агенту целиком]",
      "caption": "Файл для вас и команды. Показывать ли его кому-то ещё — решать вам."
    },
    {
      "type": "compare",
      "before": {
        "label": "Разовая удача",
        "text": "С экспортом в CSV агент справился отлично.",
        "note": "Через месяц не вспомнить, что сработало и почему."
      },
      "after": {
        "label": "Система",
        "text": "Цикл, образец PR и настройки записаны в docs/agents.md.",
        "note": "Следующая задача начинается с готового процесса."
      }
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Без секретов в заметках",
      "text": "Ключи, внутренние адреса и данные клиентов не место в репозитории — даже в документе для своих. Ссылайтесь на настройки, а не копируйте их значения (шаг 4.4)."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Процесс важнее модели",
      "text": "Модели и инструменты сменятся. Критерии, ревью и автоматические проверки останутся — их и держите в порядке, пересматривая файл, когда меняется проект."
    },
    {
      "type": "sources",
      "links": [
        {
          "title": "Расширения Claude Code: CLAUDE.md, навыки, хуки, субагенты",
          "url": "https://code.claude.com/docs/en/features-overview"
        },
        {
          "title": "Память: CLAUDE.md проекта",
          "url": "https://code.claude.com/docs/en/memory"
        }
      ]
    },
    {
      "type": "text",
      "text": "На этом маршрут пройден. Дальше — та же цепочка на каждой задаче: с каждым разом она занимает меньше внимания и даёт больше результата."
    }
  ],
  "practice": {
    "task": "Соберите в `docs/agents.md` своего проекта цикл задачи, ссылки на PR из шага ★.1 и сравнение из ★.2, а также на настройки агента. Запишите следующую задачу, которую отдадите агенту целиком.",
    "done": [
      "в одном файле — цикл задачи, образец и ссылки на настройки проекта;",
      "в файле нет ключей, внутренних адресов и чужих данных;",
      "записана следующая задача для агента."
    ]
  },
  "verified": {
    "date": "2026-10-07",
    "claudeCode": "2.1.292"
  }
}$json$::jsonb where step_id = 'public-profile';
delete from private.guide_checks where step_id = 'public-profile';

commit;
